actions.script:
const L = (text) => ec.l10n.localize(text)
// a check list posts one value, several, or none
const toList = (value) => value == null || value === '' ? [] : typeof value === 'string'
    ? value.split(',') : Array.from(value)
const names = (value) => Array.from(new Set(toList(value).flatMap((text) => String(text).split(/[,\s]+/))
    .map((text) => text.trim().toLowerCase()).filter((text) => text)))
const on = (value) => toList(value).some((text) => String(text) === 'Y' || String(text) === 'true')
// a DNS name with a domain: not an IP address, one label, or localhost (moqui_core::edge::setup::check_host_name)
const publicName = (name) => name.length <= 253 && /^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/.test(name)
    && /[a-z]/.test(name.split('.').pop()) && name !== 'localhost' && !name.endsWith('.localhost')
const choices = {
    webOn: on(webOn), passthroughNames: names(passthroughNames), terminateNames: names(terminateNames),
    mailOn: on(mailOn), mailDomains: names(mailDomains), systemMail: on(systemMail),
    emailAccountIds: toList(emailAccountIds).map(String),
    chatOn: on(chatOn), chatBridgeIds: toList(chatBridgeIds).map(String),
    passOn: on(passOn), passSites: toList(passSites).flatMap((text) => String(text).split(','))
        .map((text) => text.trim()).filter((text) => text),
    passCallback: String(passCallback || '').trim(),
    xmppOn: on(xmppOn), xmppDomain: String(System.getProperty('xmpp_domain') || '').trim().replace(/\.$/, '').toLowerCase(),
    // calls only when the form showed the choice (the edge node's media node was up); else Apply leaves
    // this node's edge_calls_enabled as it is
    callsOffered: on(callsOffered), callsOn: on(callsOffered) && on(callsOn),
    // phones the same way (the edge node's SIP engine was up), for edge_sip_enabled
    sipOffered: on(sipOffered), sipOn: on(sipOffered) && on(sipOn)}
if (!choices.webOn && !choices.mailOn && !choices.chatOn && !choices.passOn && !choices.xmppOn && !choices.callsOn && !choices.sipOn) {
    ec.message.addError(L('Turn on at least one area')); return }
if (choices.webOn && !choices.passthroughNames.length && !choices.terminateNames.length) {
    ec.message.addValidationError(null, 'passthroughNames', null, L('Enter a host name, or turn web access off'), null); return }
if (choices.mailOn && !choices.mailDomains.length) {
    ec.message.addValidationError(null, 'mailDomains', null, L('Enter a mail domain, or turn mail off'), null); return }
if (choices.passOn && (!choices.passSites.length || !/^https?:\/\/[^/\s]+\/\S*$/.test(choices.passCallback))) {
    ec.message.addValidationError(null, 'passCallback', null, L('Choose the sites and enter the SSO callback address, with its path'), null); return }
// the whole setup is checked here too, so Apply never stops half way on a bad name (apply#EdgeSetup checks again)
const badName = choices.passthroughNames.concat(choices.terminateNames).find((name) => !publicName(name))
if (choices.webOn && badName) {
    ec.message.addValidationError(null, 'passthroughNames', null, ec.resource.expand('${name} is not a public host name', '', {name: badName}), null); return }
const badDomain = choices.mailDomains.find((domain) => !publicName(domain))
if (choices.mailOn && badDomain) {
    ec.message.addValidationError(null, 'mailDomains', null, ec.resource.expand('${name} is not a mail domain', '', {name: badDomain}), null); return }
const badId = choices.chatBridgeIds.concat(choices.passSites).find((id) => !/^[A-Za-z0-9_.-]{1,63}$/.test(id))
if (badId) { ec.message.addError(ec.resource.expand('${id} is not an id', '', {id: badId})); return }
if (choices.xmppOn && !publicName(choices.xmppDomain)) {
    ec.message.addValidationError(null, 'xmppOn', null, L('This node runs no XMPP server with a public domain: set xmpp_domain'), null); return }
// uploads (https://<domain>) and /xmpp-websocket ride on web access: the domain is one of the host names
if (choices.xmppOn && choices.webOn && !choices.passthroughNames.concat(choices.terminateNames).includes(choices.xmppDomain)) {
    choices.passthroughNames.push(choices.xmppDomain)
    ec.message.addMessage(ec.resource.expand('${name} is added to the passthrough names, for XMPP uploads and the WebSocket', '', {name: choices.xmppDomain}), 'info')
}
// with web access off the names are left as they are, so the edge node must have the domain already
// (apply#EdgeSetup checks again); a probe of the offer, so a link that is down is said, not raised
if (choices.xmppOn && !choices.webOn) {
    let nodeHosts = null
    ec.message.pushErrors()
    try {
        const offered = ec.service.sync().name('org.moqui.impl.EdgeServices.get#EdgeOffer').call() || {}
        if (!ec.message.hasError()) nodeHosts = Array.from(offered.offer?.nodeHosts || [])
            .map((host) => String(host.hostName || '').replace(/\.$/, '').toLowerCase())
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (nodeHosts == null) {
        ec.message.addValidationError(null, 'xmppOn', null, L('The edge node did not answer, so its host names for XMPP are not known: try again, or turn web access on'), null); return }
    if (!nodeHosts.includes(choices.xmppDomain)) {
        ec.message.addValidationError(null, 'xmppOn', null, ec.resource.expand('XMPP uploads and the WebSocket need ${name} as a host name on the edge node: turn web access on', '', {name: choices.xmppDomain}), null); return }
}
// the most names a setup may send (moqui_core::edge::setup::MAX_NAMES), the XMPP domain counted
if (choices.passthroughNames.length + choices.terminateNames.length > 64) {
    ec.message.addValidationError(null, 'passthroughNames', null, L('At most 64 host names, the XMPP domain counted'), null); return }
ec.web.sessionAttributes.edgeSetup = JSON.stringify(choices)
// a changed choice is applied again before it is tested
ec.web.sessionAttributes.remove('edgeApplied')
ec.web.sessionAttributes.remove('edgeTested')

const L = (text) => ec.l10n.localize(text)
const link = ec.service.sync().name('org.moqui.impl.EdgeServices.get#LinkStatus').call() || {}
notBuilt = link.state === 'notBuilt'
notStarted = link.state === 'notStarted'
const running = !notBuilt && !notStarted
// an edge or all-in-one node takes links; the wizard is a local node's (plans/Edge-Node.md §10)
isEdge = running && ['edge', 'all-in-one'].includes(link.nodeRole)
notPaired = running && !isEdge && (!link.state || link.state === 'unpaired')
offerError = ''
hasOffer = false
notAvailableText = ''
if (!running || isEdge || notPaired) return
// the offer, asked on the link: a probe (Practices-App-Dev §4), so a link that is down is shown, not raised
let out = {}
ec.message.pushErrors()
try {
    out = ec.service.sync().name('org.moqui.impl.EdgeServices.get#EdgeOffer').call() || {}
    if (ec.message.hasError()) offerError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (offerError) return
hasOffer = true
const offer = out.offer || {}
const mail = offer.mail || {}
const chat = offer.chat || {}
const pass = offer.pass || {}
const xmpp = offer.xmpp || {}
mailAvailable = !!mail.available
chatAvailable = !!chat.webhooks
passAvailable = !!pass.available
// XMPP: the edge node's tunnel ports, to this node's own XMPP server (xmpp_domain)
xmppDomain = String(System.getProperty('xmpp_domain') || '').trim().replace(/\.$/, '').toLowerCase()
const xmppPorts = [xmpp.port ? xmpp.port + ' (STARTTLS)' : '', xmpp.tlsPort ? xmpp.tlsPort + ' (' + L('direct TLS') + ')' : '']
    .filter((text) => text).join(', ')
xmppAvailable = !!xmpp.available && !xmpp.otherNode && !xmpp.needsNode
xmppOtherNode = !!xmpp.available && !!xmpp.otherNode
xmppNeedsNode = !!xmpp.available && !!xmpp.needsNode
xmppPortsText = xmppPorts
// calls: the edge node as media node of this node's calls (E7), its media address and TURN
const calls = offer.calls || {}
callsAvailable = !!calls.available
callsOtherNodes = callsAvailable && !!calls.otherNodes
callsMediaText = String(calls.mediaAddress || '')
const turnUrls = Array.from(calls.turnUrls || [])
// phones: the edge node's SIP engine (E8), with this node's trunks (the replicated set voiceTrunks) and their
// numbers, which go through it, and the numbers' fallbacks (voiceFallbacks) for while this node is away
const sip = offer.sip || {}
sipAvailable = !!sip.available
sipOtherNodes = sipAvailable && !!sip.otherNodes
sipAddressText = [sip.sipAddress ? sip.sipAddress + ' (UDP/TCP)' : '', sip.tlsAddress ? sip.tlsAddress + ' (TLS)' : '']
    .filter((text) => text).join(', ')
sipList = []
sipSummary = {}
if (sipAvailable) {
    const loaded = new Map(Array.from(sip.trunks || []).map((trunk) => [trunk.voiceTrunkId, trunk]))
    const trunks = Array.from(ec.entity.find('moqui.call.VoiceTrunk').orderBy('voiceTrunkId').limit(200).disableAuthz().list())
        .filter((trunk) => trunk.disabled !== 'Y')
    const numbers = Array.from(ec.entity.find('moqui.call.PhoneNumber').orderBy('phoneNumber').limit(1000).disableAuthz().list())
    const covered = new Set(Array.from(ec.entity.find('moqui.call.PhoneNumberFallback').limit(1000).disableAuthz().list())
        .map((row) => row.phoneNumber))
    sipList = trunks.map((trunk) => {
        const own = numbers.filter((number) => number.voiceTrunkId === trunk.voiceTrunkId)
        const there = loaded.get(trunk.voiceTrunkId)
        return {trunkText: (trunk.name || trunk.voiceTrunkId) + (trunk.host ? ' · ' + trunk.host : ''),
            numbersText: own.map((number) => number.phoneNumber).join(', ') || L('No numbers'),
            fallbackText: ec.resource.expand('${n} of ${m}', '', {n: own.filter((number) => covered.has(number.phoneNumber)).length, m: own.length}),
            stateText: there ? there.state + (there.error ? ': ' + there.error : '') : L('Not loaded there yet')}
    })
    const onTrunks = numbers.filter((number) => trunks.some((trunk) => trunk.voiceTrunkId === number.voiceTrunkId))
    sipSummary = {
        registrarText: sip.registrar ? ec.resource.expand('On, realm ${realm}: phones made here get verifiers for it', '', {realm: sip.domain || ''})
            : L('Off: outside phones cannot register to the edge node (sip_registrar_enabled there)'),
        fallbackSummaryText: ec.resource.expand('${n} of ${m} numbers have a fallback (their voicemail box, or an outside number)', '',
            {n: onTrunks.filter((number) => covered.has(number.phoneNumber)).length, m: onTrunks.length})}
}
// xmpp and calls too, for an edge node from before their areas that still lists them as not available
const areaNames = {calls: L('calls'), sip: L('phones'), xmpp: L('XMPP chat clients')}
notAvailableText = Array.from(offer.notAvailable || []).map((area) => areaNames[area] || area).join(', ')
offerText = {
    publicNamesText: Array.from(offer.publicNames || []).join(', '),
    mailText: mailAvailable ? ec.resource.expand('MX ${mx}, the ${mta}', '', {mx: mail.mxHost || '',
        mta: mail.mta === 'moqui' ? L('MTA in moqui') : L('Postfix beside it')}) : L('No mail'),
    chatText: chatAvailable ? (chat.publicUrl || out.edgeUrl || '') : L('No webhooks'),
    passText: passAvailable ? L('mr-pass') : L('No mr-pass'),
    xmppText: xmpp.available ? ec.resource.expand('Tunnel ports ${ports}', '', {ports: xmppPorts}) +
        (xmpp.otherNode ? ' (' + L('to another local node') + ')' : '') +
        (xmpp.needsNode ? ' (' + L('to no node: set edge_xmpp_node') + ')' : '') : L('No XMPP tunnel'),
    callsText: callsAvailable ? ec.resource.expand('Media node at ${address}', '', {address: callsMediaText}) +
        ' · ' + (turnUrls.length ? ec.resource.expand('TURN ${urls}', '', {urls: turnUrls.join(', ')}) : L('no TURN'))
        : L('No media node'),
    sipText: sipAvailable ? ec.resource.expand('SIP at ${addresses}', '', {addresses: sipAddressText}) + ' · ' +
        (sip.registrar ? L('registrar on') : L('registrar off')) + ' · ' +
        ec.resource.expand('${n} trunks loaded', '', {n: Array.from(sip.trunks || []).length}) : L('No SIP engine')}
// this node's choices: kept from an earlier visit, else filled in from the offer and this node's records
let kept = null
try { kept = JSON.parse(ec.web.sessionAttributes.edgeSetup || 'null') } catch (e) { kept = null }
const nodeHosts = Array.from(offer.nodeHosts || [])
// this node's own name, unless it is no public one (localhost, the default, or a name with one label)
let ownHost = String(System.getProperty('webapp_http_host') || '').trim().toLowerCase().split(':')[0]
if (!ownHost.includes('.') || ownHost === 'localhost' || ownHost.endsWith('.localhost') || /^[0-9.]+$/.test(ownHost)) ownHost = ''
const passthrough = nodeHosts.filter((host) => host.modeEnumId !== 'EdgeHostTerminate').map((host) => host.hostName)
if (ownHost && !nodeHosts.some((host) => host.hostName === ownHost)) passthrough.unshift(ownHost)
const terminate = nodeHosts.filter((host) => host.modeEnumId === 'EdgeHostTerminate').map((host) => host.hostName)
const accounts = ec.entity.find('moqui.basic.email.EmailAccount')
    .condition('accountKindEnumId', 'in', ['EakHosted', 'EakShared']).orderBy('emailAddress').limit(200).disableAuthz().list()
accountOptions = Array.from(accounts).filter((account) => account.statusId !== 'EasRemoved')
    .map((account) => ({emailAccountId: account.emailAccountId, emailAddress: account.emailAddress}))
const domains = Array.from(new Set(accountOptions.map((account) => String(account.emailAddress || '').split('@')[1] || '')
    .map((domain) => domain.trim().toLowerCase()).filter((domain) => domain)))
bridgeOptions = Array.from(ec.entity.find('moqui.chat.ChatBridge').orderBy('name').limit(200).disableAuthz().list())
    .map((bridge) => ({chatBridgeId: bridge.chatBridgeId, name: bridge.name || bridge.chatBridgeId}))
siteOptions = ec.entity.isEntityDefined('mantle.public.PublicSite')
    ? Array.from(ec.entity.find('mantle.public.PublicSite').orderBy('name').limit(200).disableAuthz().list())
        .map((site) => ({siteId: site.siteId, name: site.name || site.siteId})) : []
const client = String(pass.clientId || 'edge')
const registeredSites = String(System.getProperty('pass_client_' + client + '_sites') || '').split(',').map((site) => site.trim()).filter((site) => site)
const firstHost = passthrough[0] || terminate[0] || ''
// the system's mail goes through the edge node by default only when it has no server of its own yet
const systemServer = ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', 'SYSTEM').disableAuthz().one()
const systemHost = String(systemServer?.smtpHost || '')
systemHasHost = !!systemHost && systemHost !== 'edge:'
// choices kept from an earlier visit: a name the edge node has for this node now is kept, never dropped
mergedNames = []
if (kept) {
    const listed = new Set((kept.passthroughNames || []).concat(kept.terminateNames || []))
    for (const host of nodeHosts) {
        if (listed.has(host.hostName)) continue
        mergedNames.push(host.hostName)
        if (host.modeEnumId === 'EdgeHostTerminate') kept.terminateNames = (kept.terminateNames || []).concat([host.hostName])
        else kept.passthroughNames = (kept.passthroughNames || []).concat([host.hostName])
    }
}
mergedText = mergedNames.join(', ')
choices = kept || {
    webOn: true, passthroughNames: passthrough, terminateNames: terminate,
    mailOn: mailAvailable && accountOptions.length > 0, mailDomains: domains, systemMail: !systemHasHost,
    emailAccountIds: accountOptions.map((account) => account.emailAccountId),
    chatOn: chatAvailable && bridgeOptions.length > 0, chatBridgeIds: bridgeOptions.map((bridge) => bridge.chatBridgeId),
    passOn: false, passSites: registeredSites,
    passCallback: String(System.getProperty('pass_client_' + client + '_callback') || '') ||
        (firstHost ? 'https://' + firstHost + '/account/Sso' : ''),
    xmppOn: xmppAvailable && !!xmppDomain,
    // on when offered, unless this node turned it off before (edge_calls_enabled)
    callsOn: callsAvailable && calls.enabled !== false,
    // the same for phones (edge_sip_enabled)
    sipOn: sipAvailable && sip.enabled !== false}
form = {webOn: choices.webOn ? 'Y' : '', passthroughNames: (choices.passthroughNames || []).join(', '),
    terminateNames: (choices.terminateNames || []).join(', '),
    mailOn: choices.mailOn ? 'Y' : '', mailDomains: (choices.mailDomains || []).join(', '),
    systemMail: choices.systemMail ? 'Y' : '', emailAccountIds: choices.emailAccountIds || [],
    chatOn: choices.chatOn ? 'Y' : '', chatBridgeIds: choices.chatBridgeIds || [],
    passOn: choices.passOn ? 'Y' : '', passSites: siteOptions.length ? (choices.passSites || []) : (choices.passSites || []).join(', '),
    passCallback: choices.passCallback || '', xmppOn: choices.xmppOn ? 'Y' : '', callsOn: choices.callsOn ? 'Y' : '',
    callsOffered: callsAvailable ? 'Y' : '', sipOn: choices.sipOn ? 'Y' : '', sipOffered: sipAvailable ? 'Y' : ''}
hasSites = siteOptions.length > 0
